-- V110: Fix Traffic Signs Encoding + Restore All Damaged Sign Data
-- Strategy: CONVERT Mojibake first for undamaged rows, then restore the 21 damaged rows by overwriting with correct authoritative values.
-- Sources: signs.json (FR/NL/EN), signs_backup JSON (AR), V90 migration (structure)

SET NAMES utf8mb4;

-- ============================================================
-- PHASE 1: Fix remaining Mojibake encoding for non-Arabic columns
-- Each column uses its OWN WHERE condition (no cross-column side effects)
-- Only affects rows still containing actual Mojibake patterns (C383/C382 bytes)
-- ============================================================

-- Fix remaining 1 corrupted Arabic row in name_ar
UPDATE traffic_signs
SET name_ar = CONVERT(BINARY(CONVERT(name_ar USING latin1)) USING utf8mb4)
WHERE HEX(name_ar) LIKE '%C383%' OR HEX(name_ar) LIKE '%C382%';

-- Fix corrupted French rows in name_fr
UPDATE traffic_signs
SET name_fr = CONVERT(BINARY(CONVERT(name_fr USING latin1)) USING utf8mb4)
WHERE HEX(name_fr) LIKE '%C383%' OR HEX(name_fr) LIKE '%C382%';

-- Fix corrupted Dutch rows in name_nl
UPDATE traffic_signs
SET name_nl = CONVERT(BINARY(CONVERT(name_nl USING latin1)) USING utf8mb4)
WHERE HEX(name_nl) LIKE '%C383%' OR HEX(name_nl) LIKE '%C382%';

-- Fix corrupted Arabic rows in description_ar
UPDATE traffic_signs
SET description_ar = CONVERT(BINARY(CONVERT(description_ar USING latin1)) USING utf8mb4)
WHERE description_ar IS NOT NULL AND (HEX(description_ar) LIKE '%C383%' OR HEX(description_ar) LIKE '%C382%');

-- Fix corrupted French rows in description_fr
UPDATE traffic_signs
SET description_fr = CONVERT(BINARY(CONVERT(description_fr USING latin1)) USING utf8mb4)
WHERE description_fr IS NOT NULL AND (HEX(description_fr) LIKE '%C383%' OR HEX(description_fr) LIKE '%C382%');

-- Fix corrupted Dutch rows in description_nl
UPDATE traffic_signs
SET description_nl = CONVERT(BINARY(CONVERT(description_nl USING latin1)) USING utf8mb4)
WHERE description_nl IS NOT NULL AND (HEX(description_nl) LIKE '%C383%' OR HEX(description_nl) LIKE '%C382%');

-- Fix corrupted Arabic rows in long_description_ar
UPDATE traffic_signs
SET long_description_ar = CONVERT(BINARY(CONVERT(long_description_ar USING latin1)) USING utf8mb4)
WHERE long_description_ar IS NOT NULL AND (HEX(long_description_ar) LIKE '%C383%' OR HEX(long_description_ar) LIKE '%C382%');

-- Fix corrupted French rows in long_description_fr
UPDATE traffic_signs
SET long_description_fr = CONVERT(BINARY(CONVERT(long_description_fr USING latin1)) USING utf8mb4)
WHERE long_description_fr IS NOT NULL AND (HEX(long_description_fr) LIKE '%C383%' OR HEX(long_description_fr) LIKE '%C382%');

-- Fix corrupted Dutch rows in long_description_nl
UPDATE traffic_signs
SET long_description_nl = CONVERT(BINARY(CONVERT(long_description_nl USING latin1)) USING utf8mb4)
WHERE long_description_nl IS NOT NULL AND (HEX(long_description_nl) LIKE '%C383%' OR HEX(long_description_nl) LIKE '%C382%');

-- ============================================================
-- PHASE 2: Restore the 21 signs damaged by accidental double-conversion
-- These rows had correct data that was double-converted to '?????'
-- Restoring from backup JSON and signs.json (authoritative sources)
-- ============================================================

-- 2a: Restore Arabic (name_ar, description_ar, long_description_ar)
-- Part 1: Restore 20 damaged signs (all 3 Arabic columns)
UPDATE traffic_signs SET name_ar='ممنوع الوقوف', description_ar='ممنوع الوقوف', long_description_ar='تشير هذه العلامة المرورية إلى أن وقوف السيارات محظور في هذا الموقع، ولكن يسمح بالتوقف المؤقت للسماح للركاب بالدخول أو الخروج.' WHERE sign_code='E1';
UPDATE traffic_signs SET name_ar='لا توقف ومواقف السيارات', description_ar='لا توقف ومواقف السيارات', long_description_ar='تشير هذه العلامة المرورية إلى أن التوقف والوقوف ممنوع تماماً في هذا الموقع لأي سبب من الأسباب. المخالفة تؤدي إلى غرامة مرورية.' WHERE sign_code='E3';
UPDATE traffic_signs SET name_ar='ممنوع ركن السيارات من 1 إلى 15 من الشهر', description_ar='ممنوع ركن السيارات من 1 إلى 15 من الشهر', long_description_ar='تشير هذه العلامة المرورية إلى منع الوقوف خلال النصف الأول من كل شهر على هذا الجانب من الطريق. وتهدف هذه اللائحة إلى المحافظة على انسيابية حركة المرور ومنع الطريق من الميل إلى أحد الجانبين.' WHERE sign_code='E5';
UPDATE traffic_signs SET name_ar='ممنوع ركن السيارات من يوم 16 حتى نهاية الشهر', description_ar='ممنوع ركن السيارات من يوم 16 حتى نهاية الشهر', long_description_ar='تشير هذه العلامة المرورية إلى منع الوقوف خلال النصف الثاني من كل شهر (من اليوم 16 إلى يوم 31) على هذا الجانب من الطريق. وتهدف هذه اللائحة إلى الحفاظ على تدفق حركة المرور.' WHERE sign_code='E7';
UPDATE traffic_signs SET name_ar='مواقف للسيارات الكهربائية', description_ar='مواقف للسيارات الكهربائية', long_description_ar='تشير هذه العلامة المرورية إلى أنه يسمح بوقوف السيارات الكهربائية فقط. هذه المساحة مخصصة حصريًا للسيارات التي تعمل بالطاقة الكهربائية وغالبًا ما تكون مجهزة بنقطة شحن.' WHERE sign_code='E9a';
UPDATE traffic_signs SET name_ar='وقوف السيارات مسموح به', description_ar='وقوف السيارات مسموح به', long_description_ar='تشير هذه العلامة المرورية إلى السماح بوقوف جميع أنواع المركبات دون استثناء. ولا يقتصر على نوع معين من المركبات.' WHERE sign_code='E9a-v2';
UPDATE traffic_signs SET name_ar='مكان لوقوف السيارات للشحن الكهربائي', description_ar='مكان لوقوف السيارات للشحن الكهربائي', long_description_ar='تشير إشارة المرور هذه إلى أن مكان ركن السيارة مخصص للسيارات الكهربائية التي تحتاج إلى الشحن. يجب أن تكون السيارة متصلة بمحطة الشحن أثناء وقوفها.' WHERE sign_code='E9a-v3';
UPDATE traffic_signs SET name_ar='وقوف السيارات لفترة محدودة مع قرص وقوف السيارات', description_ar='وقوف السيارات لفترة محدودة مع قرص وقوف السيارات', long_description_ar='يُسمح بوقوف السيارات هنا لفترة محدودة (بحد أقصى 30 دقيقة). مطلوب قرص وقوف السيارات. لا يسمح بتمديد وقت وقوف السيارات. إذا كنت ترغب في البقاء لفترة أطول، يجب عليك مغادرة مكان وقوف السيارات والعودة في وقت لاحق.' WHERE sign_code='E9a-v6';
UPDATE traffic_signs SET name_ar='مواقف سيارات للأشخاص ذوي الإعاقة', description_ar='مواقف سيارات للأشخاص ذوي الإعاقة', long_description_ar='مكان ركن السيارات هذا مخصص للأشخاص الذين يحملون بطاقة إعاقة رسمية صادرة عن الحكومة. لا يُسمح للمركبات الأخرى بالوقوف هنا. لا يُسمح بالتوقف المؤقت إلا في حالة بقاء السائق خلف عجلة القيادة.' WHERE sign_code='E9a-v7';
UPDATE traffic_signs SET name_ar='E9a مسموح بوقوف السيارات', description_ar='E9a مسموح بوقوف السيارات', long_description_ar='علامة وقوف السيارات: اتبع قواعد وقوف السيارات المشار إليها.' WHERE sign_code='E9a-v10';
UPDATE traffic_signs SET name_ar='مواقف للسيارات فقط', description_ar='مواقف للسيارات فقط', long_description_ar='تشير هذه العلامة المرورية إلى أن هذا المكان مخصص حصراً للسيارات الخاصة الصغيرة التي يبلغ وزنها الأقصى 3.5 طن. لا يُسمح للشاحنات أو الحافلات التي يزيد وزنها عن 3.5 طن بالوقوف هنا.' WHERE sign_code='E9b';
UPDATE traffic_signs SET name_ar='مواقف للشاحنات فقط', description_ar='مواقف للشاحنات فقط', long_description_ar='تشير إشارة المرور هذه إلى أن مكان ركن السيارات هذا مخصص حصراً للشاحنات الخفيفة لنقل البضائع. لا يُسمح لجميع المركبات الأخرى بالوقوف هنا.' WHERE sign_code='E9c';
UPDATE traffic_signs SET name_ar='مواقف للسيارات للحافلات فقط', description_ar='مواقف للسيارات للحافلات فقط', long_description_ar='تشير هذه الشاخصة المرورية إلى أن هذا المكان لوقوف السيارات مخصص حصراً لحافلات النقل العام أو الحافلات السياحية. يحظر على جميع المركبات الأخرى الوقوف هنا.' WHERE sign_code='E9d';
UPDATE traffic_signs SET name_ar='وقوف السيارات الإلزامي على حافة أو الرصيف', description_ar='وقوف السيارات الإلزامي على حافة أو الرصيف', long_description_ar='تشير هذه العلامة المرورية إلى أنه يجب على السائقين ركن سيارتهم بشكل كامل على الرصيف. يمنع الوقوف بشكل جزئي على الطريق أو في وسطه كما هو موضح في الشاخصة.' WHERE sign_code='E9e';
UPDATE traffic_signs SET name_ar='ركن السيارة بشكل جزئي على الحافة أو الرصيف', description_ar='ركن السيارة بشكل جزئي على الحافة أو الرصيف', long_description_ar='تتطلب هذه العلامة المرورية من السائقين ركن سيارتهم جزئيًا على الرصيف، مع وضع بعض العجلات على الرصيف والباقي على الطريق. وعادة ما تستخدم هذه الطريقة على الطرق الضيقة لتسهيل حركة المرور.' WHERE sign_code='E9f';
UPDATE traffic_signs SET name_ar='وقوف السيارات الإلزامية على الطريق', description_ar='وقوف السيارات الإلزامية على الطريق', long_description_ar='تتطلب هذه العلامة المرورية من السائقين ركن سياراتهم بشكل كامل على الطريق. يمنع منعاً باتاً الصعود على الرصيف ولو جزئياً. ويهدف ذلك إلى حماية الأرصفة للمشاة وضمان سلامتهم.' WHERE sign_code='E9g';
UPDATE traffic_signs SET name_ar='E9g وقوف السيارات الإلزامي على الطريق', description_ar='E9g وقوف السيارات الإلزامي على الطريق', long_description_ar='علامة وقوف السيارات: اتبع قواعد وقوف السيارات المشار إليها.' WHERE sign_code='E9g-v1';
UPDATE traffic_signs SET name_ar='موقف سيارات لعربات الكارافانات فقط', description_ar='موقف سيارات لعربات الكارافانات فقط', long_description_ar='مساحة وقوف السيارات هذه مخصصة حصريًا لعربات الكارافانات والكرفانات المخصصة للتخييم والرحلات الطويلة. لا يُسمح للمركبات العادية بالوقوف هنا.' WHERE sign_code='E9h';
UPDATE traffic_signs SET name_ar='مواقف للدراجات النارية فقط', description_ar='مواقف للدراجات النارية فقط', long_description_ar='مساحة وقوف السيارات هذه مخصصة للدراجات النارية حصريًا. يمنع منعا باتا وقوف السيارات أو المركبات الأخرى هنا.' WHERE sign_code='E9i';
UPDATE traffic_signs SET name_ar='مواقف سيارات نصف شهرية', description_ar='مواقف سيارات نصف شهرية', long_description_ar='تنظم هذه العلامة المرورية وقوف السيارات حسب التاريخ من الشهر. من اليوم 1 إلى اليوم 15، يُسمح بالوقوف على الجانب الذي به أرقام فردية، ومن اليوم 16 إلى نهاية الشهر فقط على الجانب الذي يحتوي على أرقام زوجية.' WHERE sign_code='E11';
